#include<iostream>
#include<cstdio>
#include<cstring>
#include<algorithm>
#include<cmath>
#define rep(i,a,b) for(int i=(a);i<=(b);i++)
#define rop(i,a,b) for(int i=(a);i<(b);i++)
#define per(i,a,b) for(int i=(a);i>=(b);i--)
#define por(i,a,b) for(int i=(a);i>(b);i--)
using namespace std;
typedef long long ll;
const ll mod=1e9+7;
ll n,k,S[502][502],A[502][502],_A[502][502],S_A[502][502];
char s[502];

bool isl(char c) {return c=='('||c=='?';} 
bool isr(char c) {return c==')'||c=='?';} 
bool isx(char c) {return c=='*'||c=='?';} 

int main(){
	scanf("%lld%lld%s",&n,&k,s+1);
	rep(l,1,n){ 
		if(!isx(s[l])) continue; 
		S[l][l]=1;
		rep(r,l+1,min(n,l+k-1)){ 
			if(!isx(s[r])) break; 
			S[l][r]=1;
		}
	}
	per(l,n-1,1){
		rep(r,l+1,n){
			if(r-l==1){ 
				if(isl(s[l])&&isr(s[r])) A[l][r]=_A[l][r]=1; 
				continue;
			}
			if(isl(s[l])&&isr(s[r])){ 
				A[l][r]+=S[l+1][r-1],A[l][r]%=mod; 
				A[l][r]+=A[l+1][r-1],A[l][r]%=mod; 
				rop(i,l+1,r-1) A[l][r]+=S[l+1][i]*A[i+1][r-1]%mod,A[l][r]%=mod; 
				rop(i,l+1,r-1) A[l][r]+=A[l+1][i]*S[i+1][r-1]%mod,A[l][r]%=mod; 
			}
			_A[l][r]=A[l][r]; 
			rop(i,l,r) S_A[l][r]+=S[l][i]*_A[i+1][r]%mod,S_A[l][r]%=mod; 
			rop(i,l,r) A[l][r]+=A[l][i]*_A[i+1][r]%mod,A[l][r]%=mod; 
			rop(i,l,r) A[l][r]+=A[l][i]*S_A[i+1][r]%mod,A[l][r]%=mod; 
		}
	}
	printf("%lld",A[1][n]);
	return 0;
}
